from bs4 import BeautifulSoup
from unidecode import unidecode

def extract_text_with_breaks(html):
    # Parse the HTML
    soup = BeautifulSoup(html, 'html.parser')
    
    # Get the <body> tag; return empty string if none exists
    body = soup.body
    if not body:
        return ""
    
    # Replace all <br> tags with newline characters (\n)
    for br in body.find_all("br"):
        br.replace_with("\n")
    
    # Extract text, inserting newlines between text from different tags
    text = body.get_text(separator='\n')
    
    # Clean up extra blank lines (optional)
    text = '\n'.join(line for line in text.split('\n') if line.strip())
    
    return text

